/*
 * Self-destructing service worker.
 *
 * The site previously used the Chirpy theme, which registered a PWA service
 * worker at "/sw.min.js" that cached the whole site offline. After migrating to
 * the jekyll-98 theme, that old worker keeps serving stale cached pages in
 * returning visitors' browsers. Serving this replacement at the same path makes
 * the browser update the worker, which then clears all caches, unregisters
 * itself, and reloads open tabs so the fresh site loads from the network.
 */
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});
